24	// registryCandidates returns all URL variants to look up in the engine's auth
25	// file.
26	func registryCandidates(registryURL string) []string {
27		base := strings.TrimSuffix(registryURL, "/")
28	
29		// Check if this URL is any known Docker Hub alias; if so, return the full set.
30		if isDockerHubKey(base) {
31			return dockerHubKeys
32		}
33	
34		// Generic: bare hostname, https://, http:// variants.
35		candidates := []string{base}
36		if strings.HasPrefix(base, "https://") {
37			candidates = append(candidates, strings.TrimPrefix(base, "https://"))
38		} else if strings.HasPrefix(base, "http://") {
39			candidates = append(candidates, strings.TrimPrefix(base, "http://"))
40		} else {
41			candidates = append(candidates, "https://"+base, "http://"+base)
42		}
43		return candidates
44	}
