183	// authFile is the part of the engine's auth file the login state reads.
184	type authFile struct {
185		Auths       map[string]authEntry `json:"auths"`
186		CredsStore  string               `json:"credsStore"`
187		CredHelpers map[string]string    `json:"credHelpers"`
188	}
