190	// RegistryLoginState reports whether credentials are stored for registryURL,
191	// and whether their secret is inline in the auth file or held by a helper.
192	//
193	// What `login` writes, measured on 2026-09-25 (docker 29.7.2, podman 5.7.0):
194	//
195	//	                 docker                     podman
196	//	no helper        auths[host] = {"auth":…}   auths[host] = {"auth":…}
197	//	credsStore       auths[host] = {}           ignored — written inline
198	//	credHelpers      auths[host] = {}           no auths entry at all
199	//
200	// Any inline secret wins, even next to a helper: a login made before the
201	// helper was configured leaves its base64 behind, and docker then ignores it
202	// without removing it — it is still on disk. Only the podman credHelpers case
203	// needs the helper itself asked, since the file keeps no trace of the login.
204	func RegistryLoginState(registryURL string) LoginState {
205		var cfg authFile
206		if err := readAuthFile(&cfg); err != nil {
207			return LoginNone
208		}
209		for _, phase := range credentialPhases(registryURL) {
210			if state := loginStateOf(cfg, phase); state != LoginNone {
211				return state
212			}
213		}
214		return LoginNone
215	}
