217	// loginStateOf is RegistryLoginState for one lookup phase.
218	func loginStateOf(cfg authFile, phase credentialPhase) LoginState {
219		found := false
220		for _, c := range phase.candidates {
221			entry, ok := cfg.Auths[c]
222			if !ok {
223				continue
224			}
225			if entry.inline() {
226				return LoginInline
227			}
228			found = true
229		}
230		host := phase.helperHost
231		if found {
232			// An empty entry holds nothing by itself: the secret is in the helper,
233			// and with no helper configured there is no secret anywhere.
234			if cfg.CredHelpers[host] != "" || cfg.CredsStore != "" {
235				return LoginHelper
236			}
237			return LoginNone
238		}
239		if helper := cfg.CredHelpers[host]; helper != "" {
240			if _, _, ok := getCredsFromHelper(helper, host); ok {
241				return LoginHelper
242			}
243		}
244		return LoginNone
245	}
