248	// helpers are keyed on.
249	func helperHost(registryURL string) string {
250		host := strings.TrimSuffix(registryURL, "/")
251		for _, prefix := range []string{"https://", "http://"} {
252			host = strings.TrimPrefix(host, prefix)
253		}
254		return host
255	}
