257	// RegistryLogout removes stored credentials for an OCI registry.
258	// It runs `<engine> logout` (cleans system credential stores) then directly
259	// removes all matching keys from the engine's auth file to handle cases where
260	// logout leaves behind alias entries (e.g. docker.io vs https://index.docker.io/v1/).
261	func RegistryLogout(registryURL string) error {
262		if err := requireEngine(); err != nil {
263			return err
264		}
265		if err := mutate(cmdLabel("logout"), "logout", registryURL); err != nil {
266			return err
267		}
268		// Also remove all matching alias keys directly from config.json.
269		_ = removeFromAuthFile(registryURL)
270		return nil
