273	// removeFromAuthFile removes all URL variants of registryURL from the auths
274	// section of the engine's credential file. Errors are non-fatal (best effort).
275	func removeFromAuthFile(registryURL string) error {
276		configPath, err := authPath()
277		if err != nil {
278			return err
279		}
280	
281		var raw map[string]json.RawMessage
282		if err := readAuthFile(&raw); err != nil {
283			return err
284		}
285		authsRaw, ok := raw["auths"]
286		if !ok {
287			return nil
288		}
289		var auths map[string]json.RawMessage
290		if err := json.Unmarshal(authsRaw, &auths); err != nil {
291			return err
292		}
293	
294		changed := false
295		for _, candidate := range registryCandidates(registryURL) {
296			if _, exists := auths[candidate]; exists {
297				delete(auths, candidate)
298				changed = true
299			}
300		}
301		if !changed {
302			return nil
303		}
304	
305		updated, err := json.Marshal(auths)
306		if err != nil {
307			return err
308		}
309		raw["auths"] = updated
310		out, err := json.MarshalIndent(raw, "", "\t")
311		if err != nil {
312			return err
313		}
314		return os.WriteFile(configPath, out, 0600)
315	}
