317	// GetStoredCreds retrieves registry credentials for registryURL from the
318	// engine's auth file. It tries the per-registry credential helper
319	// (credHelpers), then the global credsStore, and finally falls back to the
320	// inline base64-encoded auth field. Returns ok=false when no credentials are
321	// found.
322	func GetStoredCreds(registryURL string) (username, password string, ok bool) {
323		var cfg authFile
324		if err := readAuthFile(&cfg); err != nil {
325			return "", "", false
326		}
327	
328		for _, phase := range credentialPhases(registryURL) {
329			if u, p, ok := storedCredsOf(cfg, phase); ok {
330				return u, p, true
331			}
332		}
333		return "", "", false
334	}
335	
336	// storedCredsOf is GetStoredCreds for one lookup phase.
337	func storedCredsOf(cfg authFile, phase credentialPhase) (username, password string, ok bool) {
338		helper := cfg.CredHelpers[phase.helperHost]
339		if helper == "" {
340			helper = cfg.CredsStore
341		}
342		if helper != "" {
343			if u, p, ok := getCredsFromHelper(helper, phase.helperHost); ok {
344				return u, p, true
345			}
346		}
347	
348		for _, candidate := range phase.candidates {
349			if entry, ok := cfg.Auths[candidate]; ok && entry.Auth != "" {
350				if u, p, ok := decodeAuth(entry.Auth); ok {
351					return u, p, true
352				}
353			}
354		}
355		return "", "", false
356	}
357	
358	// decodeAuth splits a base64 "username:password" auth field.
359	func decodeAuth(auth string) (username, password string, ok bool) {
360		decoded, err := base64.StdEncoding.DecodeString(auth)
361		if err != nil {
362			return "", "", false
363		}
364		if idx := strings.IndexByte(string(decoded), ':'); idx >= 0 {
365			return string(decoded[:idx]), string(decoded[idx+1:]), true
366		}
367		return "", "", false
368	}
