370	// getCredsFromHelper calls `docker-credential-<helper> get` and parses the JSON response.
371	func getCredsFromHelper(helper, serverURL string) (username, password string, ok bool) {
372		out, err := runner.Run(dockerCmd{
373			Args:   []string{"get"},
374			Stdin:  serverURL,
375			Helper: helper,
376		})
377		if err != nil {
378			return "", "", false
379		}
380		var result struct {
381			Username string `json:"Username"`
382			Secret   string `json:"Secret"`
383		}
384		if err := json.Unmarshal(out, &result); err != nil {
385			return "", "", false
386		}
387		if result.Secret == "" {
388			return "", "", false
389		}
390		return result.Username, result.Secret, true
391	}
