14	// dockerHubKeys lists all keys Docker uses for Docker Hub in ~/.docker/config.json.
15	// `docker login docker.io` stores credentials under "https://index.docker.io/v1/".
16	var dockerHubKeys = []string{
17		"docker.io",
18		"registry-1.docker.io",
19		"https://index.docker.io/v1/",
20		"https://index.docker.io/v1",
21		"https://registry-1.docker.io",
22	}
