24	// registryCandidates returns all URL variants to look up in the engine's auth
25	// file.
26	func registryCandidates(registryURL string) []string {
27		base := strings.TrimSuffix(registryURL, "/")
28	
29		// Check if this URL is any known Docker Hub alias; if so, return the full set.
30		if isDockerHubKey(base) {
31			return dockerHubKeys
32		}
33	
34		// Generic: bare hostname, https://, http:// variants.
35		candidates := []string{base}
36		if strings.HasPrefix(base, "https://") {
37			candidates = append(candidates, strings.TrimPrefix(base, "https://"))
38		} else if strings.HasPrefix(base, "http://") {
39			candidates = append(candidates, strings.TrimPrefix(base, "http://"))
40		} else {
41			candidates = append(candidates, "https://"+base, "http://"+base)
42		}
43		return candidates
44	}
45	
46	// hostKey is the host[:port] of registryURL as written (https:// assumed when it
47	// has no scheme), when that differs from what registryCandidates already tries:
48	// ok is false for a URL without a path, an unparsable one, and a Docker Hub
49	// alias. The port is kept as written, never added or dropped: nexus.example and
50	// nexus.example:443 are two keys, as in the CLI's own ConvertToHostname
51	// (DEVDESK-635). It is what `docker login <host>:<port>` stores for a registry
52	// whose entry URL carries a path (a Nexus /repository/<name> connector).
53	func hostKey(registryURL string) (key string, ok bool) {
54		raw := strings.TrimSuffix(registryURL, "/")
55		if !strings.Contains(raw, "://") {
56			raw = "https://" + raw
57		}
58		u, err := url.Parse(raw)
59		if err != nil || u.Host == "" || (u.Path == "" && u.RawQuery == "") {
60			return "", false
61		}
62		if isDockerHubKey(u.Host) {
63			return "", false
64		}
65		return u.Host, true
66	}
67	
68	// credentialPhase is one lookup of stored credentials: the auth-file keys to
69	// try and the address the credential helpers are asked.
70	type credentialPhase struct {
71		candidates []string
72		helperHost string
73	}
74	
75	// credentialPhases lists the lookups in order: the exact candidates with
76	// helperHost(registryURL), then, when hostKey applies, registryCandidates(key)
77	// with key as the helper host. The first phase that finds a login wins, so an
78	// exact key always beats the host's. GetStoredCreds and RegistryLoginState
79	// share it; logout does not (it stays on the exact key).
80	func credentialPhases(registryURL string) []credentialPhase {
81		phases := []credentialPhase{{registryCandidates(registryURL), helperHost(registryURL)}}
82		if key, ok := hostKey(registryURL); ok {
83			phases = append(phases, credentialPhase{registryCandidates(key), key})
84		}
85		return phases
86	}
