88	// isDockerHubKey reports whether base (no trailing slash) is a Docker Hub alias.
89	func isDockerHubKey(base string) bool {
90		for _, alias := range dockerHubKeys {
91			if strings.EqualFold(base, strings.TrimSuffix(alias, "/")) {
92				return true
93			}
94		}
95		return false
96	}
