100	// ~/.config/containers/auth.json under podman.
101	//
102	// The JSON is the same shape on both sides (`auths`, `credHelpers`,
103	// `credsStore`); only the location moves, which is why every reader and writer
104	// below is unchanged apart from where it points. It is read *and written*
105	// directly rather than through the CLI because `logout` leaves alias keys
106	// behind — that is what made the path a friction rather than a detail (§3.67).
107	func authPath() (string, error) {
108		path := engine.Current().AuthPath()
109		if path == "" {
110			return "", errors.New("cannot locate the container engine's credential file")
111		}
112		return path, nil
113	}
