201	// helper was configured leaves its base64 behind, and docker then ignores it
202	// without removing it — it is still on disk. Only the podman credHelpers case
203	// needs the helper itself asked, since the file keeps no trace of the login.
204	func RegistryLoginState(registryURL string) LoginState {
205		var cfg authFile
206		if err := readAuthFile(&cfg); err != nil {
207			return LoginNone
